import{_ as a,o,c as t,a2 as d}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function n(r,e,l,c,s,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Current version: <strong>0.3.2</strong>. This page is generated from <code>CHANGELOG.md</code> in the Keel repo by <code>npm run gen:changelog</code>; edit that file, not this one.</p><h2 id="_0-3-2" tabindex="-1">0.3.2 <a class="header-anchor" href="#_0-3-2" aria-label="Permalink to &quot;0.3.2&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The <code>note-lookup</code> hook&#39;s header comment pointed at <code>Docs/Systems/Tooling.md</code>, which in a game is <code>Docs/Systems/Keel/Tooling.md</code>; it now names both (comment only, no behaviour change).</li></ul><h3 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None.</li></ul><h2 id="_0-3-1" tabindex="-1">0.3.1 <a class="header-anchor" href="#_0-3-1" aria-label="Permalink to &quot;0.3.1&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Release process only (no Luau changed): every version stays a Git tag, and only a <strong>major</strong> version (<code>v1.0.0</code>, <code>v2.0.0</code>, ...) also gets a GitHub Release. A new workflow, &quot;Release (majors only)&quot;, creates it when the tag is pushed, with notes from this changelog (the major&#39;s Migration first, then everything since the previous major). Minors, patches and every <code>0.x</code> version stay tags only. See the Releasing Keel guide.</li></ul><h3 id="migration-1" tabindex="-1">Migration <a class="header-anchor" href="#migration-1" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. <code>keel.js</code> still installs from tags; nothing in a game changes.</li></ul><h2 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Frame hooks.</strong> Any Service, Controller or System can define <code>PreSimulation(dt)</code> (every frame, before physics: for velocities and forces physics must see this frame) and <code>PreRender(dt)</code> (every frame, just before drawing, client only: for the camera). The Loader hands them to the Scheduler when Start returns, like <code>Update</code>. They get the same protection as <code>Update</code>: guarded, slow calls logged, and a hook that waits is stopped. Unity&#39;s closest are <code>FixedUpdate</code> and <code>LateUpdate</code>, but Roblox has no fixed step: <code>dt</code> is the frame&#39;s real time.</li><li><code>Scheduler.AddFrame(module, &quot;PreSimulation&quot; | &quot;PreRender&quot;)</code>. Game code rarely calls it; the Loader does.</li><li><code>Types.Module</code> has the two optional fields.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>Scheduler.Remove(module)</code> stops every hook of the module, not only <code>Update</code>.</li><li>Scheduler log lines name the hook (<code>Name.PreSimulation: …</code>); <code>Update</code> lines read as before.</li><li>The Loader stops the boot if a module&#39;s <code>PreSimulation</code> or <code>PreRender</code> isn&#39;t a function, or if a server module has a <code>PreRender</code> (there is no rendering on the server).</li></ul><h3 id="migration-2" tabindex="-1">Migration <a class="header-anchor" href="#migration-2" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. Modules without the new hooks behave exactly as before. A module that connects its own <code>RunService.PreSimulation</code> or <code>PreRender</code> can move that code into the matching method to get the Scheduler&#39;s guard and logging.</li></ul><h2 id="_0-2-3" tabindex="-1">0.2.3 <a class="header-anchor" href="#_0-2-3" aria-label="Permalink to &quot;0.2.3&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>LogOff</code> understands <code>*</code> (mute every tag) and <code>-Name</code> (exempt one tag from <code>*</code>): <code>*,-Replica</code> mutes everything except <code>Replica</code>.</li><li><code>Log.Only(tag)</code> writes that for you. <code>Log.Set(&#39;*&#39;, enabled)</code> mutes or restores all tags.</li><li>Console: <code>log &amp;lt;tag&gt; only</code> mutes every other tag, and <code>log * off</code> / <code>log * on</code> mute or restore everything. The tag argument autocompletes <code>*</code>.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The <code>log</code> command&#39;s reply lists the <code>LogOff</code> entries now set (for example <code>LogOff: *, -Replica</code>) instead of <code>muted: ...</code>.</li></ul><h3 id="migration-3" tabindex="-1">Migration <a class="header-anchor" href="#migration-3" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. An existing <code>LogOff</code> value such as <code>Data,Replica</code> works as before.</li></ul><h2 id="_0-2-2" tabindex="-1">0.2.2 <a class="header-anchor" href="#_0-2-2" aria-label="Permalink to &quot;0.2.2&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>keel.js update</code> no longer deletes and recreates the owned folders (<code>Keel</code>, <code>KeelServer</code>, ...). It overwrites files in place, deletes only files Keel dropped (and folders left empty), so Studio&#39;s Script Sync stays connected and you no longer reconnect after an update.</li></ul><h3 id="migration-4" tabindex="-1">Migration <a class="header-anchor" href="#migration-4" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>The update <em>to</em> 0.2.2 still runs the old <code>keel.js</code>, so reconnect Script Sync on <code>Keel</code> and <code>KeelServer</code> once after it. Updates after that keep the connection.</li></ul><h2 id="_0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#_0-2-1" aria-label="Permalink to &quot;0.2.1&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Docs only: the Replica and State note records that the two-player privacy check passed live (a client reads other players&#39; <code>Public</code> state and <code>nil</code> for their <code>Owner</code> state; right after joining it reads <code>nil</code> until the snapshot arrives, so use <code>State.Observe</code>). No code changed.</li></ul><h3 id="migration-5" tabindex="-1">Migration <a class="header-anchor" href="#migration-5" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None.</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Keel Setup</strong>, a Studio plugin (<code>tools/KeelSetup.lua</code>, an owned file) that creates the six root Folders and the optional place attributes, and lists the Script Sync connects still to make. Studio cannot script the connect itself, and a template place file does not keep the connections, so the connects stay manual.</li><li><code>keel.js new</code> prints the plugin install step and the next steps in Studio.</li><li>A documentation site in <code>site/</code> (VitePress): getting started, tutorials, guides, an API reference generated from the source, and a changelog page. Not copied into games.</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Releasing now requires every change to be documented in the same release, with deprecations, new features and kits recorded in the changelog (see <code>site/guides/releasing-keel.md</code>).</li></ul><h3 id="migration-6" tabindex="-1">Migration <a class="header-anchor" href="#migration-6" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. After <code>node tools/keel.js update v0.2.0</code> a game has <code>tools/KeelSetup.lua</code>; copy it into Studio&#39;s Plugins folder if you want the plugin.</li></ul><h2 id="_0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#_0-1-1" aria-label="Permalink to &quot;0.1.1&quot;">​</a></h2><p><code>keel.js</code> writes text files with LF line endings (a Windows clone had CRLF, which StyLua rejected). New games get a <code>.gitattributes</code> that keeps LF on checkout.</p><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p>First version. Extracted from StealTheGun (commit <code>7831be3</code>): Loader, Scheduler, Signal, Trove, Log, Net (Packet), Defs, Entity, Data (ProfileStore), State and Replica, Client layer (Input, UIController, View, Widget), Console (Cmdr), Purchases, Policy, LiveDefs, the unit test runner and its specs, plus the starter game files, tooling and notes.</p>',47)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
